/**
 * @name Path Traversal
 * @description Detecting potential path traversal vulnerabilities where user input controls file paths.
 * @kind problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider function parameters as potential sources for library code
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks: open(), os.path.join, etc.
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTraversalFlow::flow(source, sink)
select sink, "Potential path traversal from $@", source, "source"
